type TestCategory = 'A_CONNECTION' | 'B_DATA' | 'C_SECURITY' | 'D_NETWORK' | 'E_CLOUD';
type TestStatus = 'IDLE' | 'RUNNING' | 'PASSED' | 'FAILED';

interface PortPoint {
  x: number;
  y: number;
}

interface OpcUaLogEntry {
  id: number;
  time: string;
  service: string;
  direction: string;
  nodeId: string;
  details: string;
  statusCode: string;
  result: 'Success' | 'Delivered' | 'Rejected' | 'Failed' | 'Recovered';
}

interface TestDefinition {
  id: string;
  num: number;
  name: string;
  category: TestCategory;
  isFault: boolean;
  safeAuto: boolean;
  expectedResult: string;
  conflictsWith?: string[];
}

interface TestRuntimeRecord {
  enabled: boolean;
  status: TestStatus;
  actualResult: string;
  timestamp: string;
}

interface TestHistoryItem {
  id: number;
  time: string;
  testName: string;
  action: 'ON' | 'OFF' | 'RUN';
  status: TestStatus;
  detail: string;
}

