  const fwRightRef = useRef<HTMLSpanElement | null>(null);
  const dmzLeftRef = useRef<HTMLSpanElement | null>(null);
  const dmzRightRef = useRef<HTMLSpanElement | null>(null);
  const dmzBotRef = useRef<HTMLSpanElement | null>(null);
  const aggSrvLeftRef = useRef<HTMLSpanElement | null>(null);
  const aggSrvRightRef = useRef<HTMLSpanElement | null>(null);
  const entFwLeftRef = useRef<HTMLSpanElement | null>(null);
  const entFwRightRef = useRef<HTMLSpanElement | null>(null);
  const dataPlatRef = useRef<HTMLSpanElement | null>(null);
